I'll help you implement and optimize the CUDA kernel for matrix multiplication. Let's start with the first iteration.

### Iteration 1: Basic Matrix Multiplication Kernel
We'll implement a naive kernel where each thread computes one element of the output matrix. This will serve as our baseline.

```python
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# CUDA kernel source code
cuda_source = """
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

__global__ void linear_forward_kernel(const float* x, const float* weight, const float* bias, float* out, 
                                      int batch_size, int in_features, int out_features) {
    int b = blockIdx.x * blockDim.x + threadIdx.x;
    int i = blockIdx.y * blockDim.y + threadIdx.y;

    if (b < batch_size && i < out_features) {
        float value = 0.0;
        for (int j = 0; j < in_features; j++) {
            value += x[b * in_features + j] * weight[i * in_features + j];
        }
        out[b * out_features + i] = value + bias[i];
    }
}

torch::Tensor linear_forward_cuda(torch::Tensor x, torch::Tensor weight, torch::Tensor bias) {
    auto batch_size = x.size(0);
    auto in_features = x.size(1);
    auto out_features = weight.size(0);

    auto out = torch::zeros({batch_size, out_features}, x.options());

    dim3 block(16, 16);
    dim3 grid((batch_size + block.x - 1) / block.x, (out_features + block.y - 1) / block.y);

    linear_forward_kernel<<<grid, block>>>(x.data_ptr<float>(), weight.data_ptr<float>(), 
                                          bias.data_ptr<float>(), out.data_ptr<float>(),
                                          batch_size, in_features, out_features);

    return out;
}
"""

cpp_source = "torch::Tensor linear_forward_cuda(torch::Tensor x, torch::Tensor weight, torch::Tensor bias);"

# Load the CUDA kernel
linear_cuda = load_inline(
    name="linear_forward",
    cpp_sources=cpp_source,
    cuda_sources=cuda_source,
    functions=["linear_forward_cuda"],
    verbose=True
)

class ModelNew(nn.Module):
    def __init__(self, n):
        super().__init__()
        self.weight = nn.Parameter(torch.randn(n, n))
        self.bias = nn.Parameter(torch.randn(n))

    def forward(self, x):
        return linear_cuda.linear_forward_cuda(x, self.weight, self.bias)
