import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Optimized CUDA kernel with warp-level programming and vectorized loads
cuda_source = """
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

__global__ void matmul_kernel(const float* A, const float* B, float* C, 
                              int N) {
    const int TILE_SIZE = 32;
    const int WARP_SIZE = 32;
    const int WARPS_PER_BLOCK = 8;
    const int THREADS_PER_BLOCK = WARP_SIZE * WARPS_PER_BLOCK;

    __shared__ float As[WARPS_PER_BLOCK][TILE_SIZE][TILE_SIZE];
    __shared__ float Bs[WARPS_PER_BLOCK][TILE_SIZE][TILE_SIZE];

    int warp_id = threadIdx.x / WARP_SIZE;
    int lane_id = threadIdx.x % WARP_SIZE;

    int by = blockIdx.y;
    int bx = blockIdx.x;

    // Each warp computes a tile of size TILE_SIZE x TILE_SIZE
    int row = by * TILE_SIZE + warp_id * (TILE_SIZE / WARPS_PER_BLOCK);
    int col = bx * TILE_SIZE;

    float sum = 0.0f;

    for (int t = 0; t < (N + TILE_SIZE - 1) / TILE_SIZE; t++) {
        // Load tiles using vectorized loads
        for (int i = 0; i < TILE_SIZE; i += WARP_SIZE) {
            int load_idx = i + lane_id;
            if (load_idx < TILE_SIZE) {
                // Load A tile
                int A_row = row + load_idx;
                int A_col = t * TILE_SIZE + lane_id;
                if (A_row < N && A_col < N) {
                    As[warp_id][load_idx][lane_id] = A[A_row * N + A_col];
                } else {
                    As[warp_id][load_idx][lane_id] = 0.0f;
                }

                // Load B tile
